/// <summary>
/// Extension of the form <f>LedgerJournalTable</f>
/// </summary>
[ExtensionOf(formStr(LedgerJournalTable))]
internal final class AVALedgerJournalTableFrm_Extension
{
}

Method.Source:
/// <summary>
/// Initializes form controls based on the journal type.
/// </summary>
/// <param name="_journalTypeId">
/// The journal type ID
/// </param>
protected void initControls(Integer _journalTypeId)
{
    LedgerJournalType ledgerJournalType = any2Enum(_journalTypeId);

    next initControls(_journalTypeId);

    LedgerJournalTable_ds.object(fieldNum(LedgerJournalTable, AVACopiedWithDifLayer)).visible(false);
    LedgerJournalTable_ds.object(fieldNum(LedgerJournalTable, AVAPostedWithDifLayer)).visible(false);
    LedgerJournalTable_ds.object(fieldNum(LedgerJournalTable, AVAReversed)).visible(false);
    this.design().controlName(formControlStr(LedgerJournalTable, AVAledgerJournalRelatedToAllocation)).visible(false);
    LedgerJournalTable_ds.object(fieldNum(LedgerJournalTable, AVAReversalJournalId)).visible(false);
    switch (ledgerJournalType)
    {
        case LedgerJournalType::Allocation :
            if (LedgerParameters::find().AVAKoRe)
            {
                LedgerJournalTable_ds.object(fieldNum(LedgerJournalTable, AVACopiedWithDifLayer)).visible(true);
                LedgerJournalTable_ds.object(fieldNum(LedgerJournalTable, AVAPostedWithDifLayer)).visible(true);
                LedgerJournalTable_ds.object(fieldNum(LedgerJournalTable, AVAReversed)).visible(true);
                this.design().controlName(formControlStr(LedgerJournalTable, AVAledgerJournalRelatedToAllocation)).visible(true);
                LedgerJournalTable_ds.object(fieldNum(LedgerJournalTable, AVAReversalJournalId)).visible(true);
            }
            break;
    }
}

/// <summary>
/// AVA/WEN/2025/02/05   AVA_013036_ReverseJournal
/// </summary>
/// <param name = "_formControl">FormControl</param>
public void avaJumpRefReversalJournalId(FormControl _formControl)
{
    MenuFunction	menuFunction;
    Args        	args = new Args();
    LedgerJournalTable reversalJournal, allocJournal;

    allocJournal  =_formControl.formRun().dataSource(formDataSourceStr(LedgerJournalTable,LedgerJournalTable)).cursor() as LedgerJournalTable;

    if(allocJournal.AVAReversalJournalId)
    {
        reversalJournal = LedgerJournalTable::find(allocJournal.AVAReversalJournalId);

        args.record(reversalJournal);

        args.lookupRecord(reversalJournal);

        menuFunction = new MenuFunction(menuitemDisplayStr(ledgerjournaltable_allJournals), MenuItemType::Display);

        menuFunction.run(args);

    }
}
